// See https://svelte.dev/docs/kit/types#app.d.ts
// for information about these interfaces
//
// `Env` (App.Platform.env) is generated by `wrangler types` (see the `gen`
// script, and `check`/`build` which run it first) from the bindings declared
// in wrangler.jsonc — currently `DB: D1Database` (the `DB` D1 binding) and
// `ASSETS: Fetcher` (static assets). It lands in ./worker-configuration.d.ts,
// picked up via tsconfig.json's `compilerOptions.types`. Run `pnpm run gen`
// once after `pnpm install` if editor types look stale.
declare global {
	namespace App {
		interface Platform {
			env: Env;
			ctx: ExecutionContext;
			caches: CacheStorage;
			cf?: IncomingRequestCfProperties;
		}

		/**
		 * The single error body shape the API returns (§10, `server/http.ts`).
		 * `code` is stable and machine-readable — the client localizes from it
		 * (LOC-1) rather than parsing `message`.
		 */
		interface Error {
			code: string;
			message: string;
			extra?: { retryAfter?: number };
		}

		interface Locals {
			/** Guest identity from the `x-guest-id` header (§4). Null for a registered player or an anonymous read. */
			guestId: string | null;
			/** Set in Phase 2 by Better Auth; every Phase 1 caller treats it as null. */
			userId: string | null;
			/** Resolved by paraglideMiddleware (LOC-1) — cookie, then Accept-Language, then 'en'. */
			locale: import('$lib/paraglide/runtime.js').Locale;
		}

		// interface PageData {}
		// interface PageState {}
	}
}

export {};
